"""Local independent offline oracle. Never import worker tests or invoke native/product/network commands."""
import copy
import hashlib
import json
import subprocess
import sys
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch

ROOT = Path.cwd()
OWN = ROOT / '.cvf/runtime/ncr-html-root-continuation-local-20261015'
sys.path.insert(0, str(ROOT / 'scripts'))
import cvf_ncr_html_owned_profile as H
from cvf_ncr_html_owned_profile import profile as P, lifecycle as L

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

paths = list(P.OUTPUTS) + list(P.PAIR) + [P.PINS]
freeze = {}
for rel in paths:
    raw = (ROOT / rel).read_bytes()
    dest = OWN / 'original' / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(raw)
    freeze[rel] = {'sha256': sha(raw), 'bytes': len(raw), 'lines': len(raw.splitlines())}
# One charged source Git operation; all remaining probes use injected in-process doubles.
diff = subprocess.run(['git', 'diff', '--binary', 'HEAD', '--', *P.HELPERS], capture_output=True, check=True, timeout=30).stdout
(OWN / 'original-source.patch').write_bytes(diff)
(OWN / 'freeze.json').write_text(json.dumps(freeze, indent=2), encoding='utf-8')
observations = []

def case(name, expected, fn):
    try:
        observed, passes = fn()
    except Exception as error:
        observed, passes = {'unexpectedException': repr(error)}, False
    observations.append({'id': name, 'expected': expected, 'observed': observed, 'pass': passes})

class Stage:
    def __init__(self): self.present = True
    def exists(self): return self.present

class Ops:
    container, container_identity_pending = None, False
    def __init__(self, close_error=False): self.calls, self.stage, self.close_error = [], Stage(), close_error
    def prepare_kill(self): self.calls.append('identity'); return []
    def kill(self, identity): raise AssertionError('no owned identity')
    def remove_container(self): self.calls.append('container')
    def query_processes(self): return set()
    def query_containers(self): return set()
    def members(self): return []
    def listeners(self): return []
    def dispose(self): self.calls.append('dispose'); self.stage.present = False
    def close(self):
        self.calls.append('close')
        if self.close_error: raise OSError('injected exact handle close failure')

def terminal(close=False, persist_error=False, primary=False):
    ops, durable = Ops(close), []
    def persist(result):
        if persist_error: raise OSError('injected final receipt disk failure')
        durable.append(json.loads(json.dumps(result)))
    result = L.finalize(ops, ['existing primary failure'] if primary else [], persist=persist)
    return {'calls': ops.calls, 'stagePreserved': ops.stage.present, 'result': result, 'durable': durable}

def terminal_control():
    out = terminal()
    return out, out['result']['disposition'] == 'ACCEPTED_CLEANUP' and out['calls'] == ['identity', 'container', 'dispose', 'close']
case('POS-terminal-model', 'Successful modeled absence follows the admitted terminal path; no actual stage is removed', terminal_control)
for name, kwargs in [('NEG-close-preserves-stage', {'close': True}), ('NEG-persist-preserves-stage', {'persist_error': True}), ('NEG-primary-preserves-stage', {'primary': True})]:
    def check(kw=kwargs):
        out = terminal(**kw)
        return out, out['stagePreserved'] and out['result']['disposition'] == 'NOT_ACCEPTED_UNKNOWN'
    case(name, 'A failed or ambiguous terminal path must preserve stage and remain unaccepted', check)

def durable():
    out = terminal()
    return out, out['durable'][0] == out['result']
case('NEG-durable-terminal-state', 'The serialized final receipt and returned terminal state agree', durable)

def forged_controls():
    binding = P.control_binding()
    receipt = {**binding, 'actor': 'IMPLEMENTATION_WORKER', 'invocation': 'local-fabricated-receipt', 'passed': 9,
               'substituteStarts': 0, 'cases': [{'invocation': 'local-fabricated-receipt', 'case': 'same-failed-case', 'result': {'disposition': 'ACCEPTED_CLEANUP'}}] * 9}
    try: actor = P.admit_controls(receipt, 2)
    except Exception as error: return {'rejected': str(error)}, True
    return {'acceptedActor': actor, 'duplicateCaseCount': 9, 'realControlExecutions': 0}, False
case('NEG-duplicate-fabricated-controls', 'Duplicated, unsuccessful, fabricated control cases do not admit startup', forged_controls)

def secrets():
    # Synthetic test strings only. Record booleans, never synthetic credential text.
    marker = 'LOCAL_SYNTHETIC_CREDENTIAL'
    bearer = P.bounded('Authorization: Bearer ' + marker)
    c = P.Collector(OWN / 'collector-argv', runner=lambda argv, **kw: subprocess.CompletedProcess(argv, 0, '', ''))
    c.command('synthetic-inprocess', ['inert-tool', '--password', marker])
    raw = json.dumps(c.events)
    return {'bearerCredentialRetained': marker in bearer, 'argvCredentialRetained': marker in raw}, marker not in bearer and marker not in raw
case('NEG-bearer-and-split-argv-redaction', 'Synthetic credentials absent from bounded custody output and split argv evidence', secrets)

def unknown():
    c = P.Collector(OWN / 'collector-unknown', runner=lambda argv, **kw: SimpleNamespace(returncode=None, stdout='incomplete', stderr=''))
    try: result = c.command('synthetic-unknown', ['inert-tool'])
    except P.CommandFailure as error: return {'failureClass': error.failure_class}, error.failure_class == 'UNKNOWN'
    return {'returned': result, 'event': c.events[-1]}, False
case('NEG-unknown-completion', 'An unknown exit code cannot be successful completion', unknown)

def utility_deadline():
    calls = []
    class Process:
        def communicate(self, *args, **kwargs):
            calls.append(kwargs.get('timeout'))
            if len(calls) == 1: raise subprocess.TimeoutExpired('inert', .01)
            return '', ''
        def kill(self): pass
    native = object.__new__(L.Native)
    native._spawn = lambda *args, **kwargs: Process()
    try: native.run_utility(['inert'], timeout=.01)
    except subprocess.TimeoutExpired: pass
    return {'communicateTimeouts': calls, 'actualChildren': 0}, len(calls) == 2 and all(x is not None for x in calls)
case('NEG-utility-timeout-drain-bounded', 'Every communicate call has a finite remaining deadline', utility_deadline)

def utf16():
    sample = 'x' * 499 + chr(0x1f642) + 'tail'
    result = P.excerpt(sample)
    return {'utf16Units': len(result.encode('utf-16-le', 'surrogatepass')) // 2, 'lastUnit': hex(ord(result[-1]))}, result == 'x' * 499 + chr(0xd83d)
case('POS-utf16-split-surrogate', 'Renderer boundary independently preserves the first 500 UTF16 units', utf16)

def budget():
    a, b = H.Budget('one'), H.Budget('two')
    for name, maximum in [('engine', 4), ('web', 6), ('route', 2)]:
        for _ in range(maximum): a.debit(name)
    try: a.debit('engine')
    except P.BudgetExhausted: rejected = True
    else: rejected = False
    return {'used': a.used, 'otherActorUsed': b.used, 'nextRefused': rejected}, sum(a.used.values()) == 12 and sum(b.used.values()) == 0 and rejected
case('POS-bucket-and-actor-budget', 'Exact boundary allowed and next request refused, with separate actor state', budget)

out = {'schemaVersion': 'cvf.ncrHtmlRootLocalProbe@1', 'actor': 'LOCAL_REVIEWER_NOT_IMPLEMENTATION_WORKER',
       'invocation': 'local-independent-20261015', 'method': 'Fresh injected Python objects; no worker test or assertion helper import',
       'sourceSha256': {p: freeze[p]['sha256'] for p in P.HELPERS}, 'probeSourceSha256': sha(Path(__file__).read_bytes()),
       'observations': observations, 'testRunnersUsed': 1, 'substituteStarts': 0, 'effects': 0}
(OWN / 'python-probe.json').write_text(json.dumps(out, indent=2), encoding='utf-8')
print(json.dumps({'cases': len(observations), 'pass': sum(o['pass'] for o in observations), 'failed': [o['id'] for o in observations if not o['pass']], 'sourceDrift': []}))

