'use strict';
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const crypto = require('node:crypto');
if (process.env.CVF_NCR_ALLOWED_PORTS || process.env.CVF_HCR_EGRESS_LOG) throw Error('pure import guard');
const root = process.cwd();
const own = path.join(root, '.cvf/runtime/ncr-html-root-continuation-local-20261015');
const subject = require(path.join(root, 'scripts/cvf_ncr_html_owned_profile/journey.cjs'));
const input = {title:'Independent Synthetic',sourcePath:'synthetic/independent.md',sourceContent:'Local fixture',memoryClass:'FULL_RECORD',status:'Draft',claimBoundary:'Offline fixture',receiptAnchor:'local-probe'};
const observations = [];
async function exercise(closeFails) {
  const events = [], options = [];
  const page = {setDefaultTimeout: n => events.push('default:'+n), addInitScript: async () => {}, on: () => {}, goto: async () => {throw Error('injected navigation failure');}};
  const context = {route: async () => {}, pages: () => [page], close: async () => {events.push('close');if(closeFails) throw Error('injected close failure');}};
  const original = {load:Module._load,read:fs.readFileSync,write:fs.writeFileSync,destroy:process.stdin.destroy};
  let escaped;
  try {
    Module._load = function(name,...args) {if(name === 'independent-modules/@playwright/test') return {chromium:{launchPersistentContext:async (profile,opts)=>{options.push(opts);return context;}},expect:()=>{throw Error('unexpected assertion');}};return original.load.call(this,name,...args);};
    fs.readFileSync = function(name,...args) {if(name === 'independent-config') return JSON.stringify({inputs:[input],cap:1,deadlineSeconds:1,browserProfile:'inert-not-created'});return original.read.call(this,name,...args);};
    fs.writeFileSync = function(name,...args) {if(name === 'independent-output') {events.push('save');return;}throw Error('unexpected write '+name);};
    process.stdin.destroy = function(){events.push('stdin-destroy');};
    try {await subject.run({modules:'independent-modules',baseURL:'http://inert.invalid',output:'independent-output',custody:'inert',control:async()=>{},config:'independent-config'});}catch(error){escaped=String(error);}
  } finally {
    Module._load=original.load;fs.readFileSync=original.read;fs.writeFileSync=original.write;process.stdin.destroy=original.destroy;process.exitCode=0;
  }
  return {events,launchTimeout:options[0].timeout ?? null,escaped:escaped ?? null};
}
(async()=>{
  const positive=await exercise(false);
  observations.push({id:'POS-browser-terminal-model',expected:'Ordinary terminal path saves custody and attempts stdin teardown',observed:positive,pass:positive.events.includes('save')&&positive.events.includes('stdin-destroy')});
  const negative=await exercise(true);
  observations.push({id:'NEG-browser-close-does-not-skip-custody',expected:'A browser-close error cannot skip final custody and remaining teardown',observed:negative,pass:negative.events.includes('save')&&negative.events.includes('stdin-destroy')});
  observations.push({id:'NEG-browser-launch-deadline',expected:'Browser launch has the finite remaining work timeout',observed:{launchTimeout:positive.launchTimeout,remainingBudgetMs:1000},pass:positive.launchTimeout>0&&positive.launchTimeout<=1000});
  const result={actor:'LOCAL_REVIEWER_NOT_IMPLEMENTATION_WORKER',invocation:'local-independent-20261015-node',method:'Injected module loader and recording browser objects; no browser/module query/network start',probeSourceSha256:crypto.createHash('sha256').update(fs.readFileSync(__filename)).digest('hex'),observations,testRunnersUsed:1,substituteStarts:0,effects:0};
  fs.writeFileSync(path.join(own,'node-probe.json'),JSON.stringify(result,null,2));
  process.stdout.write(JSON.stringify({cases:observations.length,pass:observations.filter(x=>x.pass).length,failed:observations.filter(x=>!x.pass).map(x=>x.id)})+'\n');
})().catch(e=>{process.stderr.write(String(e)+'\n');process.exitCode=1;});

